// app/posts/[id]/page.tsx — Server Component mặc định
import 'server-only';
import { Suspense } from 'react';
import { notFound } from 'next/navigation';
import { db } from '@/lib/db';
import { renderAndSanitizeMarkdown } from '@/lib/markdown.server';
import { LikeButton } from './like-button';

type PageProps = { params: Promise<{ id: string }> };

async function PostBody({ id }: { id: string }) {
  const post = await db.post.findUnique({
    where: { id },
    select: { id: true, title: true, body: true, likes: true },
  });
  if (!post) notFound();

  const safeHtml = renderAndSanitizeMarkdown(post.body);
  return (
    <article>
      <h1>{post.title}</h1>
      <div dangerouslySetInnerHTML={{ __html: safeHtml }} />
      {/* Chỉ primitive data cần thiết đi qua client boundary. */}
      <LikeButton postId={post.id} initialLikes={post.likes} />
    </article>
  );
}

export default async function PostPage({ params }: PageProps) {
  const { id } = await params;
  return (
    <Suspense fallback={<PostSkeleton />}>
      <PostBody id={id} />
    </Suspense>
  );
}

// like-button.tsx
'use client';
export function LikeButton({ postId, initialLikes }: {
  postId: string; initialLikes: number;
}) {
  // state/event/browser interactivity nằm ở leaf boundary
  return <button onClick={() => like(postId)}>{initialLikes} likes</button>;
}

// app/actions/update-profile.ts
'use server';

import 'server-only';
import { updateTag } from 'next/cache';
import { z } from 'zod';
import { auth } from '@/lib/auth.server';
import { db } from '@/lib/db.server';

const Input = z.object({
  userId: z.string().uuid(),
  displayName: z.string().trim().min(2).max(80),
});

export async function updateProfile(formData: FormData) {
  const session = await auth();
  if (!session) return { ok: false, code: 'UNAUTHENTICATED' } as const;

  const parsed = Input.safeParse({
    userId: formData.get('userId'),
    displayName: formData.get('displayName'),
  });
  if (!parsed.success) {
    return { ok: false, code: 'INVALID_INPUT', issues: parsed.error.flatten() } as const;
  }

  // Không tin hidden userId: kiểm tra quyền trên server trong invocation.
  if (session.user.id !== parsed.data.userId && session.user.role !== 'admin') {
    return { ok: false, code: 'FORBIDDEN' } as const;
  }

  await db.user.update({
    where: { id: parsed.data.userId },
    data: { displayName: parsed.data.displayName },
  });
  updateTag(`user-${parsed.data.userId}`);
  return { ok: true } as const;
}

// app/profile/profile-form.tsx
'use client';
import { useActionState } from 'react';
import { updateProfile } from '@/app/actions/update-profile';

export function ProfileForm({ userId }: { userId: string }) {
  const [state, action, pending] = useActionState(
    async (_previous: unknown, formData: FormData) => updateProfile(formData),
    null
  );
  return (
    <form action={action}>
      <input type="hidden" name="userId" value={userId} />
      <input name="displayName" />
      <button disabled={pending}>Save</button>
      {state?.ok === false && <p>{state.code}</p>}
    </form>
  );
}

// next.config.ts — runtime-hosted app dùng Cache Components
import type { NextConfig } from 'next';
const nextConfig: NextConfig = { cacheComponents: true };
export default nextConfig;

// app/lib/posts.ts
import { cacheLife, cacheTag } from 'next/cache';

export async function getPost(id: string) {
  'use cache';
  cacheLife('hours');
  cacheTag('posts', `post-${id}`);
  return db.post.findUnique({ where: { id } });
}

// app/actions/posts.ts
'use server';
import { revalidateTag, updateTag } from 'next/cache';

export async function updateOwnDraft(id: string, input: DraftInput) {
  const user = await requireUser();
  await assertCanEdit(user, id);
  await db.post.update({ where: { id }, data: input });

  // Người vừa Save phải đọc thấy dữ liệu mới ngay.
  updateTag(`post-${id}`);
  updateTag('posts');
}

// Route Handler nhận webhook CMS
export async function POST(request: Request) {
  await verifyCmsSignature(request);
  revalidateTag('posts', 'max'); // stale-while-revalidate
  return Response.json({ revalidated: true });
}

